const fn = new Function(code + "\nreturn { normalizeUsers };");
const { normalizeUsers } = fn();
const out = normalizeUsers([
  { name: "  Ada ", age: "36" },
  { name: "Bo", age: 21 },
]);
if (out.length !== 2) throw new Error("Both entries are valid.");
if (out[0].name !== "Ada" || out[0].age !== 36) throw new Error("Names are trimmed; numeric strings become numbers.");

const fn = new Function(code + "\nreturn { normalizeUsers };");
const { normalizeUsers } = fn();
const out = normalizeUsers([null, 42, { name: "X" }, { name: "Y", age: "abc" }, { name: "Z", age: -3 }]);
if (out.length !== 1 || out[0].name !== "Z") throw new Error("Only the finite-age entry survives — everything else is dropped.");
